  return mask_res;
}

LL compute_power(LL base, LL exponent)
{
  if(exponent==0) return 1;
  LL half=compute_power(base, exponent/2);
  LL res= (half * half) % MOD;
  if(exponent & 1) res= (res * base) % MOD;
  return res;
}

